import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Absent for users who only ever signed in via an OAuth provider (e.g. Google).
  passwordHash?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

// Creates a new user. Pass a plaintext password to have it hashed and stored,
// or omit it for OAuth-only accounts (e.g. first-time Google sign-in).
export async function createUser(input: {
  email: string;
  name: string;
  password?: string;
}): Promise<User> {
  const existing = await getUserByEmail(input.email);
  if (existing) {
    throw new Error("A user with this email already exists.");
  }

  const user: User = {
    id: String(nextId++),
    email: input.email.trim().toLowerCase(),
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: input.password
      ? await bcrypt.hash(input.password, 10)
      : undefined,
  };
  users.push(user);
  return user;
}

// Checks credentials for the email + password sign-in flow. Returns the user
// on success, or null if the email is unknown, has no password set (OAuth-only
// account), or the password doesn't match.
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | null> {
  const user = await getUserByEmail(email);
  if (!user || !user.passwordHash) return null;
  const ok = await bcrypt.compare(password, user.passwordHash);
  return ok ? user : null;
}

